    chairs = image_patch.find("chair")
    if not chairs: return image_patch
    slender_chairs = [c for c in chairs if c.verify_property("chair", "slender")]
    if not slender_chairs: return chairs[0]
    silver_chairs = [s for s in slender_chairs if s.verify_property("chair", "silver")]
    if not silver_chairs: return slender_chairs[0]
    tall_silver_chairs = [t for t in silver_chairs if t.verify_property("chair", "tall")]
    if not tall_silver_chairs: return silver_chairs[0]
    return tallest_silver_chair(tall_silver_chairs)

def tallest_silver_chair(chairs: List[ImagePatch]) -> ImagePatch:
    return max(chairs, key=lambda c: c.vertical_center - c.upper)

